import{_ as t,c as a,o as e,a4 as o,a5 as r,a6 as d}from"./chunks/framework.mdxl8zx-.js";const f=JSON.parse('{"title":"浏览器相关","description":"","frontmatter":{},"headers":[],"relativePath":"frontEnd/browser/index.md","filePath":"frontEnd/browser/index.md"}'),n={name:"frontEnd/browser/index.md"},s=o('<h1 id="浏览器相关" tabindex="-1">浏览器相关 <a class="header-anchor" href="#浏览器相关" aria-label="Permalink to &quot;浏览器相关&quot;">​</a></h1><h2 id="_1、垃圾回收机制" tabindex="-1">1、垃圾回收机制 <a class="header-anchor" href="#_1、垃圾回收机制" aria-label="Permalink to &quot;1、垃圾回收机制&quot;">​</a></h2><p>可达性：某个值可以被访问到，那他一定存储在在内存当中</p><p>当某个值不可达时（当没有对内的引用时），就会被垃圾回收掉。小至一个变量，大至一个对象。</p><h3 id="原理-内部算法" tabindex="-1">原理，内部算法 <a class="header-anchor" href="#原理-内部算法" aria-label="Permalink to &quot;原理，内部算法&quot;">​</a></h3><p>垃圾回收的基本算法被称为 <strong>“mark-and-sweep”</strong></p><p>步骤：（执行广度优先算法）</p><p>1、遍历所有的根，并标记他们</p><p>2、一层一层遍历，每一层都被标记</p><p>3、没有被标记的对象都会被删除</p><p>不同的浏览器做了不同的优化，比如：</p><ul><li><strong>分代收集</strong>：分成常用的和不常用的</li><li><strong>增量收集</strong>：对一后续新增的数据进行收集，而不是对整个大的对象进行处理</li><li><strong>闲时收集</strong>：只在CPU空闲的时候执行</li></ul><h2 id="_2、dom" tabindex="-1">2、DOM <a class="header-anchor" href="#_2、dom" aria-label="Permalink to &quot;2、DOM&quot;">​</a></h2><h3 id="_1、脚本-defer和async" tabindex="-1">1、脚本：Defer和Async <a class="header-anchor" href="#_1、脚本-defer和async" aria-label="Permalink to &quot;1、脚本：Defer和Async&quot;">​</a></h3><p>两者都是加载外部脚本(Script)资源的时候<strong>不阻塞页面</strong>。仅适用于有src属性的script。</p><p><strong>Defer:</strong> 不阻塞页面，但是<strong>脚本按顺序执行</strong>，且在DOMContentLoaded<strong>生命周期之前</strong>执行。适用于需要DOM的脚本，或执行顺序有先后的脚本。</p><p><strong>Async:</strong> 不阻塞页面，加载完即执行，不与DOMContentLoaded相关。适用于独立不相关资源。</p><h3 id="_2、重绘和重排-回流" tabindex="-1">2、重绘和重排（回流） <a class="header-anchor" href="#_2、重绘和重排-回流" aria-label="Permalink to &quot;2、重绘和重排（回流）&quot;">​</a></h3><p><strong>重绘：</strong> 某些元素的外观被改变，比如字体颜色等</p><p><img src="'+r+'" alt="1709704893734"></p><p><strong>重排（回流）：</strong> 重新生成布局、重新排列元素</p><p><img src="'+d+'" alt="1709704910313"></p><p>减少重排：</p><p>1、缩小重排范围、不使用table布局</p><p>2、样式集中改变</p><p>3、对DOM的读写分离且各放一起</p><p>4、将DOM离线，display:none、处理后在上线</p><p>5、复制DOM节点操作</p><p>6、脱离文档流进行操作，position：absolute或fixed</p><p><code>重绘不一定重排，但是重排一定重绘。</code></p><h2 id="_3、浏览器存储" tabindex="-1">3、浏览器存储 <a class="header-anchor" href="#_3、浏览器存储" aria-label="Permalink to &quot;3、浏览器存储&quot;">​</a></h2><h3 id="_1、cookie和sessionstorage和localstorage" tabindex="-1">1、Cookie和sessionStorage和LocalStorage <a class="header-anchor" href="#_1、cookie和sessionstorage和localstorage" aria-label="Permalink to &quot;1、Cookie和sessionStorage和LocalStorage&quot;">​</a></h3><table tabindex="0"><thead><tr><th></th><th>Cookie</th><th>sessionStorage</th><th>LocalStorage</th></tr></thead><tbody><tr><td>大小</td><td>4K</td><td>5M甚至更多</td><td>5M甚至更多</td></tr><tr><td>销毁时间</td><td>根据服务器设置时间或者关闭浏览器</td><td>关闭浏览器</td><td>手动移除</td></tr><tr><td>请求是否携带</td><td>携带</td><td>不携带</td><td>不携带</td></tr><tr><td>作用域</td><td>所有同源窗口</td><td>同源且当前标签页</td><td>所有同源窗口</td></tr></tbody></table><h3 id="_2、indexdb" tabindex="-1">2、IndexDB <a class="header-anchor" href="#_2、indexdb" aria-label="Permalink to &quot;2、IndexDB&quot;">​</a></h3><p>浏览器内建的数据库，比LocalStorage强大的多</p><ul><li>通过支持多种类型的键，来存储 几乎任何类型的值</li><li>支撑事务的可靠性</li><li>支持键值范围查询、索引</li><li>和LocalStorage相比，可以存储更大的数据量</li></ul>',36),i=[s];function l(p,h,c,_,g,b){return e(),a("div",null,i)}const m=t(n,[["render",l]]);export{f as __pageData,m as default};
